-- GenDB engine variant Q19-commuted_comparisons: template q19.sql, kind commuted_comparisons (generated by generate.py; frozen)
SELECT
  SUM(l_extendedprice * (
    1 - l_discount
  )) AS revenue
FROM lineitem, part
WHERE
  (
    l_partkey = p_partkey
    AND $1 = p_brand
    AND p_container IN ('SM CASE', 'SM BOX', 'SM PACK', 'SM PKG')
    AND $2 <= l_quantity
    AND $2 + 10 >= l_quantity
    AND p_size BETWEEN 1 AND 5
    AND l_shipmode IN ('AIR', 'AIR REG')
    AND 'DELIVER IN PERSON' = l_shipinstruct
  )
  OR (
    l_partkey = p_partkey
    AND $3 = p_brand
    AND p_container IN ('MED BAG', 'MED BOX', 'MED PKG', 'MED PACK')
    AND $4 <= l_quantity
    AND $4 + 10 >= l_quantity
    AND p_size BETWEEN 1 AND 10
    AND l_shipmode IN ('AIR', 'AIR REG')
    AND 'DELIVER IN PERSON' = l_shipinstruct
  )
  OR (
    l_partkey = p_partkey
    AND $5 = p_brand
    AND p_container IN ('LG CASE', 'LG BOX', 'LG PACK', 'LG PKG')
    AND $6 <= l_quantity
    AND $6 + 10 >= l_quantity
    AND p_size BETWEEN 1 AND 15
    AND l_shipmode IN ('AIR', 'AIR REG')
    AND 'DELIVER IN PERSON' = l_shipinstruct
  )
